const payload = $input.first().json;
const action = payload.body?.action || '';
const validActions = ['opened', 'synchronize'];
const isValid = validActions.includes(action);
const pr = payload.body?.pull_request || {};
const repo = payload.body?.repository || {};
return [{
  json: {
    isValid,
    action,
    prNumber: pr.number || 0,
    repoFullName: repo.full_name || '',
    repoOwner: repo.owner?.login || '',
    repoName: repo.name || '',
    prTitle: pr.title || '',
    prUrl: pr.html_url || '',
    diffUrl: pr.diff_url || ''
  }
}];

const prev = $('PreparePrompt').first().json;
const geminiResp = $input.first().json;
const reviewText = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || 'Review failed: No response from Gemini';
const commentBody = '<!-- n8n-gemini-review -->\n# Code Review by Gemini\n\n' + reviewText;
const commentJson = JSON.stringify({ body: commentBody });
return [{ json: { ...prev, reviewText, commentJson } }];

const prev = $('ParseResponse').first().json;
const critMatch = prev.reviewText.match(/Critical:\s*(\d+)/);
const majMatch = prev.reviewText.match(/Major:\s*(\d+)/);
const minMatch = prev.reviewText.match(/Minor:\s*(\d+)/);
const critical = critMatch ? critMatch[1] : '?';
const major = majMatch ? majMatch[1] : '?';
const minor = minMatch ? minMatch[1] : '?';
const colorVal = parseInt(critical) > 0 ? 15158332 : parseInt(major) > 0 ? 16776960 : 3066993;
const discordBody = JSON.stringify({
  username: 'PR Review',
  embeds: [{
    title: 'PR #' + prev.prNumber + ' ' + prev.prTitle,
    url: prev.prUrl,
    color: colorVal,
    fields: [
      { name: 'Repository', value: prev.repoFullName, inline: true },
      { name: 'Critical', value: String(critical), inline: true },
      { name: 'Major', value: String(major), inline: true },
      { name: 'Minor', value: String(minor), inline: true }
    ]
  }]
});
return [{ json: { ...prev, discordBody, critical, major, minor } }];
